import { Worker } from 'node:worker_threads';
async function main(): Promise<void> {
  const w = new Worker(`
    const { parentPort } = require('node:worker_threads');
    const { Readable } = require('node:stream');
    const path = require('path');
    const EventEmitter = require('node:events');
    const util = require('node:util');
    const r = new Readable({ read() {} });
    const p = r.toArray();
    setTimeout(() => { r.push('w'); r.push(null); }, 5);
    const e = new EventEmitter();
    e.on('x', (v) => parentPort.postMessage('event ' + v));
    e.emit('x', path.basename('/a/b.txt'));
    let missing = 'none';
    try { require('node:no-such-module'); } catch (err) { missing = err.code; }
    p.then((a) => parentPort.postMessage([a.map(String), util.format('%s-%d', 'f', 3), missing]));
  `, { eval: true });
  w.on('message', (m: any) => console.log('msg', JSON.stringify(m)));
  await new Promise<void>((resolve) => w.on('exit', () => resolve()));
  console.log('done');
}
